WITH flattened AS (SELECT id, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) e AS tier_value) SELECT currency, ROUND(AVG(tier_value), 2) AS avg_tier_value, APPROX_PERCENTILE(tier_value, 0.9) AS tier_value_p90, APPROX_PERCENTILE(tier_value, 0.9) AS tier_value_p90_2, SUM(tier_value) AS total_tier_value, SUM(CASE WHEN currency = 'THB' THEN tier_value ELSE 0 END) AS thb_tier_value FROM flattened GROUP BY currency ORDER BY avg_tier_value;
